/* harmony default export */ __webpack_exports__["default"] = ({
  onLoad(e) {
    this.order_sn = e.order_sn || '';
    this.getDetail();
  },
  computed: {
    header() {
      return {
        token: this.vuex_token || '',
        uid: this.vuex_user.id || 0
      };
    },
    formdata() {
      let multipart = this.vuex_config.config && this.vuex_config.config.upload.multipart || '';
      let isObj = this.$u.test.object(multipart);
      if (isObj) {
        return this.vuex_config.config.upload.multipart;
      }
      return {};
    },
    uploadurl() {
      if (!this.vuex_config.upload) {
        return '';
      }
      return this.vuex_config.upload.uploadurl;
    }
  },
  data() {
    return {
      showForm: false,
      form: {},
      rules: {},
      count: 5,
      order_sn: '',
      info: {},
      order_goods: []
    };
  },
  methods: {
    getDetail() {
      this.$api.orderDetail({
        order_sn: this.order_sn
      }).then(res => {
        if (res.code) {
          this.info = res.data;
          this.order_goods = res.data.order_goods.filter(item => [0, 6].includes(item.salestate));
          let form = {},
            rules = {};
          this.order_goods.forEach((item, index) => {
            form['star__' + index] = 5;
            form['content__' + index] = '';
            form['images__' + index] = '';
            form['goods_id__' + index] = item.goods_id;
            rules['content__' + index] = [{
              required: true,
              message: '请输入评论内容',
              trigger: ['change', 'blur']
            }, {
              min: 5,
              message: '评论不能少于5个字',
              trigger: 'change'
            }];
          });
          this.form = form;
          this.rules = rules;
          this.showForm = true;
          this.$nextTick(() => {
            this.$refs.uForm.setRules(this.rules);
          });
        }
      });
    },
    onUploaded(e, name) {
      console.log(e, name);
      this.form['images__' + name] = e.map(item => {
        return item.response.data.url;
      }).join(',');
    },
    onRemove(index, lists, name) {
      this.form['images__' + name] = lists.map(item => {
        return item.response.data.url;
      }).join(',');
    },
    submit() {
      this.$refs.uForm.validate(valid => {
        if (valid) {
          if (!this.order_sn) {
            this.$u.toast('参数缺失！');
            return;
          }
          let form = {
            order_sn: this.order_sn
          };
          let arr = [];
          for (let [key, item] of Object.entries(this.form)) {
            let k = key.split('__');
            if (arr[k[1]] == undefined) {
              arr.push({
                content: '',
                goods_id: '',
                star: 5,
                images: ''
              });
            }
            arr[k[1]][k[0]] = item;
          }
          form.remark = arr;
          this.$api.commentAdd(form).then(res => {
            this.$u.toast(res.msg);
            if (res.code == 1) {
              setTimeout(() => {
                uni.$u.route({
                  type: 'back'
                });
              }, 1000);
            }
          });
        } else {
          console.log('验证失败');
        }
      });
    }
  }
});

